#pragma once

#include <LibBase/Error.h>
#include <LibBase/String.h>
#include <LibBase/Vector.h>
#include <LibIPC/Port.h>
#include <sys/types.h>

// Messages as endpoints generated by ipcc exchange them: an id (the
// method; answers have the high bit set) and bytes starting with the
// endpoint's magic number, then each argument: integers little-endian,
// strings and byte buffers as a 32-bit length and the bytes, vectors as a
// 32-bit count and the elements, ports and files as their index among the
// message's descriptors. A byte buffer bigger than out_of_line_threshold
// goes out of line: its length, then its index among the message's
// regions (memory the kernel shares copy-on-write rather than copying).

namespace IPC {

constexpr u32 answer_bit = 0x8000'0000;
constexpr size_t out_of_line_threshold = 16 * 1024;

// Page-aligned memory mapped here, unmapped when this is dropped.
class Region {
public:
    Region() = default;
    Region(void* address, size_t size)
        : m_address(address)
        , m_size(size)
    {
    }
    Region(Region&& other)
        : m_address(exchange(other.m_address, nullptr))
        , m_size(exchange(other.m_size, 0))
    {
    }
    Region& operator=(Region&&);
    Region(Region const&) = delete;
    Region& operator=(Region const&) = delete;
    ~Region();

    // Anonymous memory for at least `size` bytes.
    static ErrorOr<Region> create(size_t size);

    [[nodiscard]] u8* data() const { return static_cast<u8*>(m_address); }
    [[nodiscard]] size_t size() const { return m_size; }
    // No longer ours to unmap (the kernel took it).
    void forget()
    {
        m_address = nullptr;
        m_size = 0;
    }

private:
    void* m_address { nullptr };
    size_t m_size { 0 };
};

// Who sent a message, as the kernel vouches.
struct Sender {
    pid_t pid { 0 };
    uid_t uid { 0 };
    gid_t gid { 0 };
};

class Encoder {
public:
    Encoder(u32 magic, u32 id);

    [[nodiscard]] u32 id() const { return m_id; }

    void encode(bool value) { encode(static_cast<u8>(value)); }
    void encode(u8 value) { append(&value, sizeof(value)); }
    void encode(u16 value) { append(&value, sizeof(value)); }
    void encode(u32 value) { append(&value, sizeof(value)); }
    void encode(u64 value) { append(&value, sizeof(value)); }
    void encode(i8 value) { append(&value, sizeof(value)); }
    void encode(i16 value) { append(&value, sizeof(value)); }
    void encode(i32 value) { append(&value, sizeof(value)); }
    void encode(i64 value) { append(&value, sizeof(value)); }
    void encode(StringView);
    void encode(String const& value) { encode(value.view()); }
    void encode(ReadonlyBytes);
    void encode(Vector<u8> const& value) { encode(value.span()); }
    // The descriptor goes with the message (it is closed here once sent).
    void encode(Port&&);

    template<typename T>
    void encode(Vector<T> const& values)
    {
        encode(static_cast<u32>(values.size()));
        for (auto const& value : values)
            encode(value);
    }

    // For send() and call().
    [[nodiscard]] Vector<u8> const& bytes() const { return m_bytes; }
    [[nodiscard]] Vector<Port>& rights() { return m_rights; }
    [[nodiscard]] Vector<Region>& regions() { return m_regions; }

private:
    void append(void const*, size_t);

    u32 m_id;
    Vector<u8> m_bytes;
    Vector<Port> m_rights;
    Vector<Region> m_regions;
};

struct ReceivedMessage {
    u32 id { 0 };
    Vector<u8> bytes;
    Vector<Port> rights;
    Vector<Region> regions;
    Port reply; // For an answer, when the sender waits for one.
    Sender sender;
};

class Decoder {
public:
    explicit Decoder(ReceivedMessage& message)
        : m_message(message)
    {
    }

    // The endpoint the message is meant for.
    ErrorOr<void> expect_magic(u32 magic);
    [[nodiscard]] bool at_end() const { return m_position == m_message.bytes.size(); }

    ErrorOr<void> decode(bool&);
    ErrorOr<void> decode(u8& value) { return take(&value, sizeof(value)); }
    ErrorOr<void> decode(u16& value) { return take(&value, sizeof(value)); }
    ErrorOr<void> decode(u32& value) { return take(&value, sizeof(value)); }
    ErrorOr<void> decode(u64& value) { return take(&value, sizeof(value)); }
    ErrorOr<void> decode(i8& value) { return take(&value, sizeof(value)); }
    ErrorOr<void> decode(i16& value) { return take(&value, sizeof(value)); }
    ErrorOr<void> decode(i32& value) { return take(&value, sizeof(value)); }
    ErrorOr<void> decode(i64& value) { return take(&value, sizeof(value)); }
    ErrorOr<void> decode(String&);
    ErrorOr<void> decode(Vector<u8>&);
    ErrorOr<void> decode(Port&);

    template<typename T>
    ErrorOr<void> decode(Vector<T>& values)
    {
        u32 count = 0;
        TRY(decode(count));
        // Every element takes at least a byte: a bound on the count.
        if (count > m_message.bytes.size() - m_position)
            return Error::from_errno(74); // EBADMSG
        for (u32 i = 0; i < count; ++i) {
            T value {};
            TRY(decode(value));
            TRY(values.try_append(move(value)));
        }
        return {};
    }

    template<typename T>
    ErrorOr<T> decode()
    {
        T value {};
        TRY(decode(value));
        return value;
    }

private:
    ErrorOr<void> take(void*, size_t);

    ReceivedMessage& m_message;
    size_t m_position { 0 };
};

// To `send_right`, not waiting for anything back.
ErrorOr<void> send(Port const& send_right, Encoder&, bool nonblocking = false);
// To `send_right`, waiting for the answer (EPIPE if none comes).
ErrorOr<ReceivedMessage> call(Port const& send_right, Encoder&);
// The next message (EAGAIN if none and `nonblocking`; EPIPE when no sender
// is left).
ErrorOr<ReceivedMessage> receive(Port const& receive_right, bool nonblocking = false);
// The answer to `request`, through its reply right.
ErrorOr<void> answer(ReceivedMessage& request, Encoder&);

}
